export function generateTimeSlots(start:string,end:string,interval=30){if(!/^\d{2}:\d{2}$/.test(start)||!/^\d{2}:\d{2}$/.test(end))return[];const toM=(s:string)=>{const[h,m]=s.split(":").map(Number);return h*60+m};const a=toM(start),b=toM(end);if(b<=a||interval<1)return[];const out:string[]=[];for(let n=a;n<b;n+=interval){const h=Math.floor(n/60),m=n%60;const d=new Date(2000,0,1,h,m);out.push(d.toLocaleTimeString("en-CA",{hour:"numeric",minute:"2-digit"}))}return out}
