import Image from "next/image";import {eventConfig} from "@/config/eventConfig";
export default function Header(){return <header className="border-b bg-white"><div className="container flex h-20 items-center justify-between"><div className="relative h-12 w-48"><Image src="/images/success-route-logo.png" alt={eventConfig.companyName} fill className="object-contain object-left" onError={(e)=>{e.currentTarget.style.display="none"}}/><span className="absolute inset-0 -z-10 flex items-center font-extrabold text-[var(--teal)]">Success Route Inc.</span></div><a href={`tel:${eventConfig.phone.replace(/-/g,"")}`} className="font-bold text-[var(--teal)]">{eventConfig.phone}</a></div></header>}
