const qs=[["Is the Open House free?","Yes. Registration and attendance are free."],["Do I need to register?","Registration is recommended so our team can plan for attendance and prepare for your visit."],["Is my selected time a private appointment?","No. This is an Open House. The selected time simply tells us approximately when you plan to arrive."],["Can international students attend?","Yes."],["Can PGWP holders attend?","Yes."],["Can work permit holders attend?","Yes."],["Can visitors attend?","Yes."],["Will I receive individual immigration advice?","The Open House provides information about potential immigration pathways and an opportunity to discuss your circumstances. Detailed individual advice may require a separate consultation."],["Does attending guarantee PR eligibility?","No. Eligibility and immigration outcomes depend on individual circumstances and applicable Canadian immigration requirements."]];export default function FAQ(){return <section className="section bg-[var(--cream)]"><div className="container max-w-3xl"><h2 className="text-3xl font-black text-[var(--teal)]">FAQ</h2><div className="mt-6 space-y-3">{qs.map(([q,a])=><details key={q} className="card p-5"><summary className="cursor-pointer font-bold">{q}</summary><p className="mt-3 text-slate-600">{a}</p></details>)}</div></div></section>}
