import {eventConfig,EventLocation} from "@/config/eventConfig";
function dateParts(date:string,time:string){const m=time.match(/(\d+):(\d+)\s*(AM|PM)/i);if(!m)return null;let h=Number(m[1]);const min=Number(m[2]);if(m[3].toUpperCase()==="PM"&&h!==12)h+=12;if(m[3].toUpperCase()==="AM"&&h===12)h=0;return new Date(`${date}T${String(h).padStart(2,"0")}:${String(min).padStart(2,"0")}:00`)}
function stamp(d:Date){return d.toISOString().replace(/[-:]/g,"").replace(/\.\d{3}Z$/,"Z")}
export function calendarData(date:string,time:string,location:EventLocation,id:string){const s=dateParts(date,time);if(!s)return null;const e=new Date(s.getTime()+eventConfig.calendarDurationMinutes*60000);const title="Success Route – Free Immigration Open House";const description=`Success Route Immigration Pathways in Canada – Free Open House.\n\nRegistration ID: ${id}\n\nPhone: ${eventConfig.phone}`;return{s,e,title,description,address:eventConfig.addresses[location]}}
export function googleCalendarUrl(date:string,time:string,location:EventLocation,id:string){const x=calendarData(date,time,location,id);if(!x)return"#";const q=new URLSearchParams({action:"TEMPLATE",text:x.title,dates:`${stamp(x.s)}/${stamp(x.e)}`,details:x.description,location:x.address});return`https://calendar.google.com/calendar/render?${q}`}
export function downloadIcs(date:string,time:string,location:EventLocation,id:string){const x=calendarData(date,time,location,id);if(!x)return;const esc=(s:string)=>s.replace(/,/g,"\,").replace(/;/g,"\;").replace(/\n/g,"\n");const body=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Success Route//Open House//EN\r\nBEGIN:VEVENT\r\nUID:${id}@successroute.ca\r\nDTSTAMP:${stamp(new Date())}\r\nDTSTART:${stamp(x.s)}\r\nDTEND:${stamp(x.e)}\r\nSUMMARY:${esc(x.title)}\r\nLOCATION:${esc(x.address)}\r\nDESCRIPTION:${esc(x.description)}\r\nEND:VEVENT\r\nEND:VCALENDAR`;const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([body],{type:"text/calendar"}));a.download=`${id}.ics`;a.click();URL.revokeObjectURL(a.href)}
